"""Reproducible visitor-focused Explore/Compare views; scientific assets untouched."""
from pathlib import Path
import re
from redesign_web import page
ROOT=Path(__file__).resolve().parents[1];WEB=ROOT/'web/dist'

def write_changed(path,text):
    data=text.replace('\n','\r\n').encode('utf-8')
    if not path.exists() or path.read_bytes()!=data:path.write_bytes(data)

def wrap(title,active,body,script):
    return page(title,active,body,script).replace('</head>','<link rel="stylesheet" href="./visitor.css"></head>').replace('Local release 0.3','Local release 0.4')

def build():
    explore='''<main id="main" class="explore-page visitor-explore"><section class="visitor-intro"><div><p class="eyebrow">REAL LIGHT. A LITTLE CURIOSITY.</p><h1>Where will you<br>look first?</h1><p>Choose one of three places observed by NASA’s SPHEREx telescope. Start with an image. We’ll keep its context close.</p></div><aside class="available-key"><strong>What can I do here?</strong><span><i class="key-dot"></i> All three fields: explore an exposure</span><span><i class="key-dot limited"></i> M101: compare a small area across two dates</span><button class="plain-link" data-help="review">Why is comparison limited? ↗</button></aside></section><div class="field-gallery visitor-gallery" data-gallery aria-label="Choose a sky region"><p class="gallery-loading" role="status">Loading the three available sky regions…</p></div>
    <section id="explorer" class="explorer" aria-busy="true"><div class="explorer-title"><div><p class="eyebrow">ONE EXPOSURE AT A TIME</p><h2 id="explore-title">Opening your first field…</h2><p id="explore-description"></p></div><a id="compare-link" class="primary" href="./compare.html" hidden>Compare the small M101 area ↗</a></div><div class="visit-subnav"><span id="exposure-summary" aria-live="polite">Reading the local observation…</span><button id="context-source" class="source-pill" disabled>✓ Data & original sources</button></div><div id="explore-error" class="fatal" role="alert" hidden></div><div id="explore-loading" class="viewer-loading" role="status"><span class="loading-orbit" aria-hidden="true"></span><strong>Opening a real SPHEREx exposure</strong><span>Checking its file identity before showing the image.</span></div><button id="explore-retry" class="outline" hidden>Try this exposure again</button>
    <div class="explore-layout" id="explore-content" hidden><div class="explore-image-column"><div class="explore-toolbar"><div><label class="control-caption" id="exposure-label">VIEW A SINGLE EXPOSURE</label><div id="observation-timeline" class="timeline" role="group" aria-labelledby="exposure-label"></div></div><div class="zoom-controls"><button id="explore-minus" aria-label="Zoom out">−</button><output id="explore-zoom">1.0×</output><button id="explore-plus" aria-label="Zoom in">+</button><button id="explore-reset">Reset view</button></div></div><div class="explore-canvas-wrap"><canvas id="explore-canvas" tabindex="0" aria-label="Real infrared exposure. Drag or use arrow keys to move, plus and minus to zoom."></canvas><span class="canvas-stamp">SPHEREx · REAL SINGLE-BAND DATA</span></div><div class="image-explainer"><span><i class="mask-swatch"></i> Blue gaps are excluded data</span><button data-help="mask" class="plain-link">Why are there gaps?</button><button data-help="infrared" class="plain-link">What am I seeing?</button></div><p class="viewer-help">Drag to explore · + / − to zoom · Use arrow keys when the image is focused</p><details class="image-options" id="explore-options"><summary>Image appearance <span>Brightness, false color & prepared pixels</span></summary><div class="visual-controls"><label>Show brightness<select id="explore-stretch"><option value="asinh">Reveal faint light (asinh)</option><option value="log">Stronger faint-light display (log)</option><option value="linear">Proportional brightness (linear)</option></select></label><label>Single-band colors<select id="explore-palette"><option value="grayscale">Grayscale</option><option value="ember">Warm · false color</option><option value="ice">Cool · false color</option></select></label><label>Pixel display<select id="explore-interpolation"><option value="smooth">Smooth display</option><option value="nearest">Inspect prepared pixels</option></select></label><label>Contrast<input id="explore-contrast" type="range" min="0.5" max="2" step="0.05" value="1"></label></div><p>Appearance changes only. No new astronomical detail is created. Colors represent one band’s intensity.</p></details><details class="pixel-inspector"><summary>Inspect a pixel <span>Coordinates, measured intensity & wavelength</span></summary><p class="coordinate-bar" id="explore-coordinate">Move over the image to read a prepared pixel.</p><button class="plain-link" data-help="wavelength">What is wavelength?</button></details></div>
    <aside class="observation-card visitor-story"><p class="eyebrow" id="object-kind">MEET THIS FIELD</p><h3 id="object-name">A real view of the sky</h3><p id="object-story"></p><div class="look-for"><span class="eyebrow">TRY LOOKING FOR</span><p id="look-prompt"></p></div><p class="caption" id="object-caution"></p><a id="object-source" target="_blank" rel="noreferrer">Read about this object at NASA ↗</a><div class="status-callout" id="explore-status"></div><details><summary>Observation details <span>Exact dates, pixels & infrared band</span></summary><dl id="explore-facts"></dl></details><details><summary>Original archive files & calibration</summary><div id="explore-source"></div></details><button id="export-context" class="outline full" disabled>↓ Save this exposure’s view record</button><p class="caption">Downloads a source-and-settings JSON record. Time-comparison notes and ZIP exports are available in Compare.</p></aside></div></section>
    <section class="sky-context editorial-section"><div><p class="eyebrow">FIND YOUR BEARINGS</p><h2>Three places<br>on the sky.</h2><p>This coordinate schematic locates our available regions. It is a map key, not a photograph or an all-sky data viewer.</p></div><div><svg id="sky-map" viewBox="0 0 720 260" role="img" aria-label="Coordinate schematic marking the three curated fields"></svg><p class="caption">ICRS sky coordinates · right ascension increases to the left</p></div></section></main>'''
    explore=explore.replace('<div id="explore-error"','<div class="view-file-controls"><button id="open-context" class="outline" disabled>Open a saved exposure view</button><input id="import-context-file" type="file" accept=".json,application/json" hidden><p id="view-record-feedback" role="status" aria-live="polite">Use an Explore JSON record. Comparison ZIPs reopen in Compare.</p></div><div id="explore-error"',1)
    explore=explore.replace('↓ Save this exposure’s view record','↓ Save exposure view (.json)').replace('Downloads a source-and-settings JSON record. Time-comparison notes and ZIP exports are available in Compare.','Downloads the source identity and viewing settings. Use “Open a saved exposure view” to restore them later. Time-comparison notes and ZIP exports are available in Compare.')
    write_changed(WEB/'explore.html',wrap('Choose a place in the infrared sky','Explore',explore,'explore.js'))
    template=ROOT/'tools/templates/comparison_0.3.html'
    if not template.exists():template.write_bytes((WEB/'compare.html').read_bytes())
    old=template.read_text(encoding='utf-8')
    workspace=old[old.index('    <section id="workspace"'):old.index('    <section id="evidence"')]
    workspace=workspace.replace('<div class="toolbar">','<div class="toolbar visitor-toolbar">',1)
    workspace=workspace.replace('Side by side</button>','Side by side</button>').replace('A / B switch</button>','Switch dates</button>')
    workspace=workspace.replace('<button id="overlay-mode" aria-pressed="false">Wipe overlay</button>','')
    workspace=workspace.replace('<button id="blink" class="text-button" aria-pressed="false">▷ Blink</button>','')
    workspace=workspace.replace('Mark a location','Add a note').replace('Showing observation','Choose which date to show')
    extra='''<details class="comparison-extras" id="compare-extras"><summary>More ways to compare <span>Wipe overlay & optional blinking</span></summary><div><button id="overlay-mode" aria-pressed="false">Wipe overlay</button><button id="blink" class="text-button" aria-pressed="false">▷ Blink between dates</button><p>Blink is optional and stops when you leave the tab. Reduced-motion settings disable it.</p></div></details>'''
    workspace=workspace.replace('<div id="wipe-controls"',extra+'<div id="wipe-controls"',1)
    workspace=workspace.replace('<div class="visual-controls">','<details class="image-options" id="compare-options"><summary>Image appearance <span>Shared brightness, false color & pixels</span></summary><div class="visual-controls">',1)
    workspace=workspace.replace('<details class="display-settings">','</details><details class="display-settings"><summary-placeholder>',1).replace('<summary-placeholder><summary>Display settings <span>Shared intensity scale</span></summary>','<summary>Precise brightness limits <span>Advanced · shared between dates</span></summary>')
    workspace=workspace.replace('Your field notes','Your questions').replace('A question starts here.','Notice something worth checking?').replace('+ Add by coordinates','Enter a sky position instead').replace('↓ Export comparison','↓ Save comparison (.zip)').replace('↥ Reopen a saved comparison','↥ Open a saved comparison')
    workspace=workspace.replace('<div class="notebook-bottom">','<div class="notebook-bottom"><button data-help="notes" class="plain-link">What will my download contain?</button>')
    workspace=workspace.replace('Both observations use the same grayscale transform.','Both observations use the same selected intensity transform.')
    workspace=workspace.replace('<span class="utc">UTC</span>','')
    evidence=old[old.index('    <section id="evidence"'):old.index('    <section id="about"')]
    evidence=evidence.replace('Understand the comparison.','The evidence behind your view.').replace('<div id="checks" class="checks"></div>','<details><summary>Preparation checks <span>Engineering screens & review status</span></summary><div id="checks" class="checks"></div></details>')
    dialog=old[old.index('  <dialog id="note-dialog"'):old.index('<footer class="site-footer"')]
    # Make the user's question primary; keep exact coordinate entry discoverable.
    coords=dialog[dialog.index('<div class="form-grid">'):dialog.index('<label>What are you recording?')]
    dialog=dialog.replace(coords,'').replace('<p class="form-error"', '<details id="note-location"><summary>Location on the sky <span>Advanced coordinates</span></summary><p>Right ascension and declination locate your note on the celestial map. Clicking an image fills these in for you.</p>'+coords+'</details><p class="form-error"')
    dialog=dialog.replace('Choose a position in the common usable area. A note does not confirm the cause of a difference.','Describe what caught your eye. Its sky position stays attached. This is a question for review, not a confirmed change.').replace('Record your observation.','What caught your eye?').replace('What are you recording?','Type of question').replace('Your note','Your question').replace('Save field note','Save note')
    dialog=dialog.replace('<dialog id="note-dialog">','<dialog id="note-dialog" aria-labelledby="note-dialog-title">').replace('<h2>What caught your eye?</h2>','<h2 id="note-dialog-title">What caught your eye?</h2>')
    intro='''<main id="main" class="compare-page visitor-compare"><section class="visitor-compare-intro"><div><p class="eyebrow">A CLOSER LOOK AT M101</p><h1>The same place.<br>Two moments.</h1><p>Look at a small area near the Pinwheel Galaxy’s center on 7 and 11 December 2025. Keep the view steady, then save a question.</p></div><aside class="comparison-context"><span class="review-tag">Scientific approval PENDING</span><strong>One limited research comparison</strong><p>Larger areas did not pass the wavelength screen. A qualified reviewer has not yet approved this pair’s scientific interpretation.</p><button data-help="review" class="plain-link">What does pending mean?</button><a href="./explore.html?field=m101#explorer">← Return to the larger exposure</a></aside></section><ol class="visitor-journey" aria-label="Your comparison journey"><li data-journey-step="1" class="current" aria-current="step"><b>1</b><span>Look at both dates<small>Same place, shared scale</small></span></li><li data-journey-step="2"><b>2</b><span>Explore a detail<small>Switch dates or zoom</small></span></li><li data-journey-step="3"><b>3</b><span>Save a question<small>Mark, write & download</small></span></li></ol><div class="visitor-context-bar"><span>24 × 24 prepared pixels · limited field of view</span><button data-help="pixels" class="plain-link">Why is this area small?</button><button data-help="wavelength" class="plain-link">Are these the same kind of light?</button><button id="comparison-source" class="source-pill" disabled>✓ Data & original sources</button></div><div class="field-selector comparison-technical-field" hidden><select id="field"><option>M101</option></select><span id="field-position"></span></div><div id="loading" class="viewer-loading" role="status"><span class="loading-orbit" aria-hidden="true"></span><strong>Preparing your comparison</strong><span>Checking the real data, dates and common usable pixels.</span></div><div id="fatal" class="fatal" role="alert" hidden></div>'''
    body=intro+workspace+evidence+'</main>'+dialog
    body=body.replace('<span id="pair-label"','<span hidden id="pair-label"')
    source_button='<button id="comparison-source" class="source-pill" disabled>✓ Data & original sources</button>'
    body=body.replace(source_button,'',1)
    body=body.replace('REAL ARCHIVE DATA','REAL SPHEREx DATA · REVIEW PENDING')
    body=body.replace('<div id="comparison-timeline"',source_button+'<div id="comparison-timeline"',1)
    body=body.replace('<span id="pair-label"></span>','<span id="pair-label" title="Reproducible comparison identity"></span>')
    write_changed(WEB/'compare.html',wrap('Compare two moments in M101','Compare',body,'app.js'))

if __name__=='__main__':build()
